    try:records=[json.loads(line)for line in raw.decode('utf-8').split('\n')[:-1]]if raw else[]
    except(UnicodeError,ValueError)as error:raise ValueError('valid physical LF JSONL required')from error
    if len(records)!=manifest['rows']:raise ValueError('complete archive row count differs')
    previous=None
    for row in records:
